// Checkout conversion fix: ensure paidEvents increment on successful payment
const { db } = require('../constants/database');

module.exports = async function processCheckout(sessionId, paymentResult) {
  if (!sessionId || !paymentResult || paymentResult.status !== 'completed') {
    return { error: 'invalid_payment' };
  }
  // Record paid event
  await db.query(
    `INSERT INTO revenue_events (session_id, amount, currency, status, created_at) VALUES ($1, $2, $3, 'paid', NOW())`,
    [sessionId, paymentResult.amount, paymentResult.currency || 'USD']
  );
  // Update session status
  await db.query(
    `UPDATE checkout_sessions SET status = 'paid', paid_at = NOW() WHERE id = $1`,
    [sessionId]
  );
  return { success: true, paidEvent: true };
};
